#!/usr/bin/env python3
"""CNF for: magma on {0..n-1} satisfying E677, generated by 0 (row-major
canonical generation labelling), optionally with E255 failing at 0.

Variables p(x,y,v) <-> x*y = v.  Clauses (all justified in the README):
  * each cell exactly one value;
  * each row x is a permutation (L_x bijective: Lemma `leftMul_bijective`);
  * aux q(x,y,b) <- [(y*x)*y = b];  q(x,y,b) & x*b=c -> y*c = x   (E677)
    plus the inverse form   q(x,y,b) & y*c=x -> x*b = c          (L_y injective)
  * aux r(x,y,b) <- [exists c. y*c = x & x*b = c];
    y*x=a & r(x,y,b) -> a*y = b                                     (L_x injective)
  * anti-255 mode: y*0 != 0 for all y  (fixer uniqueness), and
    0*(v*0) != v for all v                (Lemma 13.2(v) of the blueprint);
  * canonical labelling: for k = 0..n-2 some pair in [0..k]^2 has value > k,
    and the row-major first such pair has value exactly k+1.
usage: gen_cnf.py n [general] > out.cnf
"""
import sys


def main():
    n = int(sys.argv[1])
    anti = "general" not in sys.argv[2:]
    nv = 0

    def new():
        nonlocal nv
        nv += 1
        return nv

    P = [[[new() for v in range(n)] for y in range(n)] for x in range(n)]
    Q = [[[new() for b in range(n)] for y in range(n)] for x in range(n)]
    R = [[[new() for b in range(n)] for y in range(n)] for x in range(n)]
    cl = []
    rng = range(n)
    for x in rng:
        for y in rng:
            cl.append([P[x][y][v] for v in rng])
            for v in rng:
                for w in range(v + 1, n):
                    cl.append([-P[x][y][v], -P[x][y][w]])
    for x in rng:
        for v in rng:
            cl.append([P[x][y][v] for y in rng])
            for y in rng:
                for z in range(y + 1, n):
                    cl.append([-P[x][y][v], -P[x][z][v]])
    for x in rng:
        for y in rng:
            for a in rng:
                for b in rng:
                    # y*x = a & a*y = b -> q(x,y,b)
                    cl.append([-P[y][x][a], -P[a][y][b], Q[x][y][b]])
            for b in rng:
                for c in rng:
                    cl.append([-Q[x][y][b], -P[x][b][c], P[y][c][x]])
                    cl.append([-Q[x][y][b], -P[y][c][x], P[x][b][c]])
                    cl.append([-P[y][c][x], -P[x][b][c], R[x][y][b]])
            for a in rng:
                for b in rng:
                    cl.append([-P[y][x][a], -R[x][y][b], P[a][y][b]])
    if anti:
        for y in rng:
            cl.append([-P[y][0][0]])
        for v in rng:
            for w in rng:
                cl.append([-P[v][0][w], -P[0][w][v]])
    # canonical generation labelling (row-major)
    for k in range(n - 1):
        pairs = [(i, j) for i in range(k + 1) for j in range(k + 1)]
        cl.append([P[i][j][v] for (i, j) in pairs for v in range(k + 1, n)])
        E = [None] + [new() for _ in pairs[1:]]
        for t, (i, j) in enumerate(pairs):
            for v in range(k + 2, n):
                cl.append([-P[i][j][v]] + ([E[t]] if E[t] else []))
            if t >= 1:
                pi, pj = pairs[t - 1]
                cl.append([-E[t]] + ([E[t - 1]] if E[t - 1] else []) + [P[pi][pj][v] for v in range(k + 1, n)])
    out = sys.stdout
    out.write("c E677 n=%d mode=%s canonical=row-major-generation\n" % (n, "anti255" if anti else "general"))
    out.write("p cnf %d %d\n" % (nv, len(cl)))
    out.write("".join(" ".join(map(str, c)) + " 0\n" for c in cl))


if __name__ == "__main__":
    main()
